import java.util.*;

class Solution {
    public List<Integer> levelOrder(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        int height = height(root);
        for (int level = 1; level <= height; level++) {
            collect(root, level, answer);
        }
        return answer;
    }

    private int height(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }

    private void collect(TreeNode node, int level, List<Integer> answer) {
        if (node == null) {
            return;
        }
        if (level == 1) {
            answer.add(node.val);
            return;
        }
        collect(node.left, level - 1, answer);
        collect(node.right, level - 1, answer);
    }
}
